5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
9	use AtrioTeam\DigitalHub\Tags\Models\Tag;
10	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
11	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
12	use Illuminate\Console\Command;
13	use Illuminate\Support\Facades\DB;
14	use Illuminate\Support\Str;
15	use OpenSpout\Reader\XLSX\Reader;
16	
17	/**
18	 * Import dei tag anagrafica dei materiali dal foglio "Materiali" del file
19	 * filtri INTERIOR (`INTERIOR - materiali e tessuti filtri.xlsx`).
20	 *
21	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
22	 * Finitura, Colore) seguite dai valori; le righe separatore (`____`) e vuote
23	 * vengono ignorate.
24	 *
25	 * Ogni blocco diventa una TagCategory (identificata dallo slug) dentro il
26	 * gruppo "Filtri Materiali Indoor" (entity_type=material, target=entity,
27	 * Category1 Indoor), ogni valore un Tag della categoria. Idempotente:
28	 * categorie e tag esistenti vengono aggiornati.
29	 */
30	class ImportIndoorFiltriMateriali extends Command
31	{
32	    protected $signature = 'app:import-indoor-filtri-materiali '
33	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
34	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
35	
36	    protected $description = 'Import dei tag anagrafica materiali dal file filtri INTERIOR (foglio "Materiali")';
37	
38	    private const SHEET = 'Materiali';
39	
40	    /**
41	     * Intestazioni di blocco (chiave normalizzata) → nome visualizzato della
42	     * TagCategory. Nel foglio compaiono con casing misto (es. "FINITURA").
43	     *
44	     * @var array<string, string>
45	     */
46	    private const BLOCKS = [
47	        'tipologia' => 'Tipologia',
48	        'finitura' => 'Finitura',
49	        'colore' => 'Colore',
50	    ];
51	
52	    public function handle(): int
53	    {
54	        $file = (string) $this->option('file');
55	        if (! is_file($file)) {
56	            $this->error("File non trovato: {$file}");
57	
58	            return self::FAILURE;
59	        }
60	
61	        $blocks = $this->parseSheet($file);
62	        if ($blocks === null) {
63	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
64	
65	            return self::FAILURE;
66	        }
67	
68	        $stats = ['categories' => 0, 'tags' => 0];
69	
70	        DB::transaction(function () use ($blocks, &$stats): void {
71	            $group = $this->resolveGroup();
72	
73	            $categorySort = 0;
74	            foreach ($blocks as $blockName => $values) {
75	                $category = TagCategory::query()->updateOrCreate(
76	                    ['tag_group_id' => $group->id, 'slug' => Str::slug($blockName)],
77	                    ['name' => ['it' => $blockName, 'en' => $blockName], 'sort' => $categorySort++],
78	                );
79	                $stats['categories']++;
80	
81	                if ($this->option('fresh')) {
82	                    Tag::query()->where('tag_category_id', $category->id)->delete();
83	                }
84	
85	                foreach ($values as $value) {
86	                    /** @var Tag|null $tag */
87	                    $tag = Tag::query()
88	                        ->where('tag_category_id', $category->id)
89	                        ->where('name->it', $value)
90	                        ->first();
91	
92	                    if ($tag === null) {
93	                        $tag = new Tag();
94	                        $tag->tag_category_id = $category->id;
95	                    }
96	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
97	                    $tag->save();
98	                    $stats['tags']++;
99	                }
100	            }
101	        });
102	
103	        $this->info('Import tag materiali completato.');
104	        $this->table(
105	            ['Metrica', 'Valore'],
106	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
107	        );
108	
109	        return self::SUCCESS;
110	    }
111	
112	    /**
113	     * Legge il foglio Materiali e raggruppa i valori per blocco.
114	     * Ritorna null se il foglio non esiste.
115	     *
116	     * @return array<string, list<string>>|null
117	     */
118	    private function parseSheet(string $file): ?array
119	    {
120	        $blocks = null;
121	        $current = null;
122	
123	        $reader = new Reader();
124	        $reader->open($file);
125	        foreach ($reader->getSheetIterator() as $sheet) {
126	            if ($sheet->getName() !== self::SHEET) {
127	                continue;
128	            }
129	            $blocks = [];
130	
131	            foreach ($sheet->getRowIterator() as $row) {
132	                $cell = $row->getCells()[0] ?? null;
133	                $raw = $cell?->getValue();
134	                $value = is_scalar($raw) ? trim((string) $raw) : '';
135	
136	                // righe vuote e separatori (____) tra i gruppi
137	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
138	                    continue;
139	                }
140	
141	                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
142	                if ($blockName !== null) {
143	                    $current = $blockName;
144	                    $blocks[$current] ??= [];
145	
146	                    continue;
147	                }
148	
149	                if ($current === null) {
150	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
151	
152	                    continue;
153	                }
154	
155	                $blocks[$current][] = $value;
156	            }
157	
158	            break;
159	        }
160	        $reader->close();
161	
162	        return $blocks;
163	    }
164	
165	    /**
166	     * Gruppo tag anagrafica dei materiali Indoor (creato se assente).
167	     * Fallisce se la Category1 "Indoor" non esiste.
168	     */
169	    private function resolveGroup(): TagGroup
170	    {
171	        $indoor = Category1::query()->where('name->it', 'Indoor')->firstOrFail();
172	
173	        return TagGroup::query()
174	            ->where('entity_type', 'material')
175	            ->where('target', TagTarget::Entity)
176	            ->where('category_1_id', $indoor->id)
177	            ->first()
178	            ?? TagGroup::query()->create([
179	                'entity_type' => 'material',
180	                'target' => TagTarget::Entity,
181	                'category_1_id' => $indoor->id,
182	                'name' => ['it' => 'Filtri Materiali Interior', 'en' => 'Interior material filters'],
183	            ]);
184	    }
185	
186	    private function normalize(string $value): string
187	    {
188	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
189	    }
190	}
